create table if not exists public.hr_tasks (id uuid primary key default gen_random_uuid(), workflow text not null check(workflow in ('onboarding','offboarding')), employee_name text not null, status text not null default 'open' check(status in ('open','in_progress','on_hold','ready','completed')), due_date date, created_at timestamptz not null default now());
create table if not exists public.hr_subtasks (id uuid primary key default gen_random_uuid(), task_id uuid not null references public.hr_tasks(id) on delete cascade, title text not null, status text not null default 'open' check(status in ('open','in_progress','on_hold','ready','completed')), created_at timestamptz not null default now());
alter table public.hr_tasks enable row level security; alter table public.hr_subtasks enable row level security;
drop policy if exists hr_tasks_rw on public.hr_tasks; create policy hr_tasks_rw on public.hr_tasks for all to authenticated using(public.has_permission('hr')) with check(public.has_permission('hr'));
drop policy if exists hr_subtasks_rw on public.hr_subtasks; create policy hr_subtasks_rw on public.hr_subtasks for all to authenticated using(public.has_permission('hr')) with check(public.has_permission('hr'));
create or replace function public.hr_onboarding_task() returns trigger language plpgsql security definer set search_path=public as $$ declare t uuid; begin insert into public.hr_tasks(workflow,employee_name,due_date) values('onboarding',new.first_name||' '||new.last_name,new.start_date) returning id into t; insert into public.hr_subtasks(task_id,title) values(t,'Check account in Entra ID'); if coalesce(new.details->>'computer','No')<>'No' then insert into public.hr_subtasks(task_id,title) values(t,'Prepare laptop'); end if; if coalesce(new.details->>'ipad','No')<>'No' then insert into public.hr_subtasks(task_id,title) values(t,'Prepare iPad'); end if; if coalesce(new.details->>'company_phone','No')='Yes' then insert into public.hr_subtasks(task_id,title) values(t,'Prepare company phone'); end if; if coalesce(new.details->>'company_sim','No')='Yes' then insert into public.hr_subtasks(task_id,title) values(t,'Prepare company SIM'); end if; return new; end $$;
drop trigger if exists hr_onboarding_task_trigger on public.hr_onboardings; create trigger hr_onboarding_task_trigger after insert on public.hr_onboardings for each row execute function public.hr_onboarding_task();
create or replace function public.hr_complete_children() returns trigger language plpgsql as $$ begin if new.status='completed' then update public.hr_subtasks set status='completed' where task_id=new.id; end if; return new; end $$;
drop trigger if exists hr_complete_children_trigger on public.hr_tasks; create trigger hr_complete_children_trigger after update of status on public.hr_tasks for each row execute function public.hr_complete_children();
create table if not exists public.hr_badge_requests (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), first_name text not null, last_name text not null, photo_path text not null, created_by uuid default auth.uid()); alter table public.hr_badge_requests enable row level security; drop policy if exists hr_badge_requests_rw on public.hr_badge_requests; create policy hr_badge_requests_rw on public.hr_badge_requests for all to authenticated using(public.has_permission('hr')) with check(public.has_permission('hr'));
